const PAGE = CARTE_1 + CARTE_2 + CARTE_3 + CARTE_4 + CARTE_5;
const offres = offresKrefel(PAGE, SOURCE);

/* ------------------------------------------------------------------ */

test('les cartes réelles sont lues, une par produit, sans doublon', () => {
  assert.equal(offres.length, 5, 'toutes les cartes doivent être lues');
  const ids = offres.map((o) => o.id);
  assert.equal(new Set(ids).size, ids.length, 'aucun produit en double');
  for (const o of offres) {
    assert.ok(o.titre && o.titre.length > 3, 'chaque offre porte un titre');
    assert.ok(o.prix > 0, 'chaque offre porte un prix');
    assert.equal(o.marchand, 'Krefel');
    assert.equal(o.pays, 'BE', 'Krefel est belge : les offres vont en Belgique');
    assert.match(o.lienMarchand, /^https:\/\/www\.krefel\.be\/(fr|nl)\/p\/\d+-/,
      'le lien mène à la fiche produit, pas à la page de rayon');
  }
});

test('le prix de référence est celui BARRÉ, et il est plus élevé', () => {
  const avecRef = offres.filter((o) => o.prixAvant != null);
  assert.ok(avecRef.length >= 1, 'au moins une carte doit porter un prix de référence');
  for (const o of avecRef) {
    assert.ok(o.prixAvant > o.prix, 'une référence plus basse n’est pas une référence');
    assert.equal(o.remise, Math.round((1 - o.prix / o.prixAvant) * 100),
      'la remise est CALCULÉE à partir des deux prix, jamais recopiée de l’écran');
  }
});

test('le pourcentage écrit à l’écran n’est jamais pris pour la remise', () => {
  for (const o of offres) {
    if (o.remise == null || o.prixAvant == null) continue;
    assert.equal(o.remise, Math.round((1 - o.prix / o.prixAvant) * 100),
      `remise incohérente avec les prix pour « ${o.titre} »`);
  }
});

test('une carte SANS prix de référence reste une offre, mais sans remise', () => {
  const sansRef = offres.filter((o) => o.prixAvant == null);
  assert.ok(sansRef.length >= 1, 'au moins une carte figée n’a pas de référence');
  for (const o of sansRef) assert.equal(o.remise, null, 'pas de référence, pas de remise');
});

test('L’EURO SE LIT AVANT OU APRÈS LE MONTANT — la panne qui a coûté 24 cartes', () => {
  // C'est LE test qui aurait évité le zéro silencieux : la page néerlandaise
  // écrit l'euro avant, la page française après. Accepter un seul ordre, c'est
  // accepter de ne rien lire sur l'autre page — sans le moindre message d'erreur.
  assert.equal(prixKrefel('€\u00a0549,00'), 549, 'néerlandais : euro avant');
  assert.equal(prixKrefel('849,00\u00a0€'), 849, 'français : euro après');
  assert.equal(prixKrefel('999,00 €'), 999);
  assert.equal(prixKrefel('€ 1.099,00'), 1099, 'milliers avec un point');
  assert.equal(prixKrefel('1.299,00 €'), 1299, 'milliers, euro après');
  // Le pourcentage affiché par le site n'est PAS un prix.
  assert.equal(prixKrefel('-15 %'), null);
  assert.equal(prixKrefel('0 avis'), null);
  assert.equal(prixKrefel('pas un prix'), null);
  assert.equal(prixKrefel(''), null);
});

test('l’identifiant suit le NUMÉRO du produit, pas le texte de l’adresse', () => {
  for (const o of offres) {
    const numero = (o.lienMarchand.match(/\/p\/(\d{4,})/) || [])[1];
    assert.ok(numero, 'le numéro de produit doit être lisible');
    assert.equal(o.id, identifiant('k', numero),
      'le slug est traduit d’une langue à l’autre : seul le numéro identifie le produit');
  }
});

test('une page vide, en maintenance ou méconnaissable ne produit RIEN d’inventé', () => {
  assert.deepEqual(offresKrefel('', SOURCE), []);
  assert.deepEqual(offresKrefel('<html><body>maintenance</body></html>', SOURCE), []);
  // La page de maintenance de krefel.be, mot pour mot : elle ne doit rien rendre.
  const maintenance = 'Sorry, onze website is even niet bereikbaar. Désolé, notre site internet est temporairement indisponible.';
  assert.deepEqual(offresKrefel(maintenance, SOURCE), []);
});
